import sys
from collections import Counter

def main():
    input = sys.stdin.read().split()
    s = input[0]
    sub = input[1]

    def can_form_with(s, sub, k):
        cnt_s = Counter(s)
        cnt_sub = Counter(sub)
        cnt_k = Counter(str(k))
        for digit, count in cnt_sub.items():
            if cnt_s[digit] < count + cnt_k.get(digit, 0):
                return False
        return True

    for k in range(1, len(s) + 1):
        if can_form_with(s, sub, k) and str(k) in s:
            remaining_digits = list(s)
            for digit in sub + str(k):
                remaining_digits.remove(digit)
            remaining_digits.sort()
            result = sub + ''.join(remaining_digits) + str(k)
            if result.startswith('0'):
                result = result[1:]
            print(result)
            return

main()
